<script lang="ts">
 import {onMount} from 'svelte';
 import {base} from '$app/paths';
 import GameTable from '$lib/components/play/GameTable.svelte';
 import {firebase} from '$lib/backend/firebase';
 import {createGame,joinGame,canResumeGame,watchGame,readGame,append,liveChannel,type LiveChannel} from '$lib/backend/repository';
 import {botCommand} from '$lib/engine/bot';
 import {applyEvent,commandEvent,replay,type State,type Command,type GameEvent,type Group} from '$lib/engine/engine';
 import type {LiveDraft} from '$lib/backend/live';
 let uid=$state(''),gameState=$state<State|null>(null),tableId=$state(''),name=$state(''),code=$state(''),error=$state(''),liveStatus=$state(''),busy=$state(false),connecting=$state(true),practice=$state(false),liveDraft=$state<LiveDraft|null>(null),copied=$state(false),replayMode=$state(false),cursor=$state(0),replayCount=$state(0),timeline=$state<GameEvent[]>([]),animationBusy=$state(false);
 let latestDraft:{groups:Group[];turn:number;purgatory:string|null}|null=null;let heartbeat:ReturnType<typeof setInterval>|undefined;let expiry:ReturnType<typeof setInterval>|undefined;let off:(()=>void)|undefined,channel:LiveChannel|undefined,botTimer:ReturnType<typeof setTimeout>|undefined,disposed=false,events:GameEvent[]=[];
 function receive(next:State,transcript?:GameEvent[]){if(disposed||replayMode)return;if(transcript&&(!gameState||next.revision>=gameState.revision))timeline=transcript;else if(practice)timeline=[...events];if(gameState&&gameState.revision>=next.revision)return;gameState=next;if(!practice)void channel?.authorize(next).catch(e=>liveStatus=e.message);scheduleBot();}
 async function connect(id:string){off?.();channel?.close();gameState=null;tableId=id;off=await watchGame(id,receive,e=>error=e.message);channel=await liveChannel(id,d=>{liveDraft=d;},e=>{liveStatus=`Live table: ${e.message}`;},()=>liveStatus='');const s=await readGame(id);receive(s);await channel.authorize(s);history.replaceState(null,'',`${base}/play?table=${id}`);localStorage.setItem('hp-table',id);}
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';try{await work();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;scheduleBot();}}
 async function send(c:Command,actor=uid){if(practice){if(!gameState)return;const e=commandEvent(gameState,actor,c,crypto.randomUUID());const next=applyEvent(gameState,e);events.push(e);localStorage.setItem('hp-practice',JSON.stringify(events));receive(next);return;}if(!gameState)return;const next=await append(tableId,gameState,actor,c);receive(next);}
 async function human(c:Command){if(replayMode||animationBusy&&c.type!=='rack')return;await run(()=>send(c));}
 function scheduleBot(){clearTimeout(botTimer);if(replayMode||!gameState||busy||animationBusy||gameState.owner!==uid||disposed)return;for(const p of gameState.players.filter(p=>p.bot)){const c=botCommand(gameState,p);if(c){botTimer=setTimeout(()=>void run(()=>send(c,p.id)),450);return;}}}
 function animationChanged(active:boolean){animationBusy=active;if(active)clearTimeout(botTimer);else scheduleBot();}
 function publish(groups:Group[],dragging:boolean,purgatory:string|null){if(gameState)latestDraft={groups,purgatory,turn:gameState.turnNumber};if(!practice&&!replayMode&&gameState&&gameState.players[gameState.turn]?.id===uid)channel?.publish({version:1,revision:gameState.revision,turn:gameState.turnNumber,actor:uid,groups,purgatory,dragging});}
 function startPractice(){off?.();channel?.close();practice=true;tableId='practice';uid='practice-player';events=[];gameState=null;const e=commandEvent(null,uid,{type:'create',name:name.trim()||'You',seed:crypto.randomUUID()},crypto.randomUUID());events.push(e);receive(applyEvent(null,e));void run(async()=>{await send({type:'bot',id:'practice-bot-1',name:'Cassiel'});await send({type:'bot',id:'practice-bot-2',name:'Ariel'});await send({type:'start'});});history.replaceState(null,'',`${base}/play?practice=1`);}
 async function copyInvite(){await navigator.clipboard.writeText(`${location.origin}${base}/play?table=${tableId}`);copied=true;setTimeout(()=>copied=false,2000);}
 async function exportReplay(){const {db}=practice||replayMode?{db:null}:await firebase();const {getDocs,collection,query,orderBy}=await import('firebase/firestore');const log=practice||replayMode?events:(await getDocs(query(collection(db!,'games',tableId,'events'),orderBy('sequence')))).docs.map(d=>{const {createdAt,...e}=d.data();return e;});const url=URL.createObjectURL(new Blob([JSON.stringify({game:'higher-powers',version:1,events:log},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`higher-powers-${tableId}.json`;a.click();URL.revokeObjectURL(url);}
 function stepReplay(value:number){cursor=value;timeline=events.slice(0,value);gameState=replay(timeline);if(!gameState.players.some(p=>p.id===uid))uid=gameState.owner;}
 async function openReplay(file:File){if(file.size>25000000)throw new Error('That replay is too large.');const data=JSON.parse(await file.text());if(data.game!=='higher-powers'||data.version!==1||!Array.isArray(data.events))throw new Error('Choose a Higher Powers replay file.');const restored=replay(data.events);off?.();channel?.close();clearTimeout(botTimer);replayMode=true;practice=false;events=data.events;timeline=[...events];replayCount=events.length;cursor=events.length;uid=restored.owner;gameState=restored;tableId='replay';}
 onMount(()=>{heartbeat=setInterval(()=>{if(gameState&&latestDraft?.turn===gameState.turnNumber&&gameState.phase==='play'&&gameState.players[gameState.turn].id===uid)publish(latestDraft.groups,false,latestDraft.purgatory);},10000);expiry=setInterval(()=>{if(liveDraft&&Date.now()-liveDraft.sentAt>45000)liveDraft=null;},2000);name=localStorage.getItem('hp-name')??'';const params=new URL(location.href).searchParams,id=params.get('table');if(params.get('practice')==='1'&&localStorage.getItem('hp-practice')){try{events=JSON.parse(localStorage.getItem('hp-practice')!);const restored=replay(events);practice=true;uid=restored.owner;tableId='practice';receive(restored);}catch{error='The saved practice game could not be replayed.';}}code=id??'';if(!id)connecting=false;void(async()=>{if(practice||replayMode)return;try{const client=await firebase();if(!practice&&!replayMode)uid=client.uid;if(id&&await canResumeGame(id))await connect(id);}catch(e){if(!practice&&!replayMode)error=e instanceof Error?e.message:String(e);}finally{connecting=false;}})();return()=>{disposed=true;off?.();channel?.close();clearTimeout(botTimer);clearInterval(expiry);clearInterval(heartbeat);};});
</script>
<svelte:head><title>Play Higher Powers</title><meta name="description" content="Play Higher Powers together at a live shared table."/></svelte:head>
{#snippet tableMenu()}<details class="table-menu"><summary aria-label="Table menu" title="Table menu"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m16 4 3 7 8 5-8 4-3 8-4-8-8-4 8-5Z"/><circle cx="16" cy="16" r="3"/></svg></summary><div>{#if !practice&&!replayMode}<button onclick={()=>void copyInvite()}>{copied?'Invite copied':'Copy invite'}</button>{/if}<button onclick={()=>void run(exportReplay)}>Save replay</button><a href={`${base}/rules.html`} target="_blank" rel="noreferrer">Rulebook ↗</a><a href={`${base}/play`}>Leave table</a></div></details>{/snippet}
<main id="main" class="play-page" class:at-table={!!gameState}>
 {#if !gameState&&!connecting}<div class="play-header"><a href={`${base}/`}>Higher <em>Powers</em></a><a href={`${base}/rules.html`} target="_blank" rel="noreferrer">Rules ↗</a></div>{/if}
 {#if error}<div class="error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if liveStatus}<p class="live-warning" role="status">{liveStatus} <button onclick={()=>void run(()=>connect(tableId))}>Reconnect</button></p>{/if}
 {#if connecting}<p>Opening the gates…</p>
 {:else if !gameState}<section class="welcome"><p class="eyebrow">THE GRAND ORDER · 3–5 PLAYERS</p><h1>Heaven is yours to rearrange.</h1><p>Bring friends to a live table, or try your Angel’s gift with two computer players.</p><label>Your name<input maxlength="40" bind:value={name} placeholder="An ambitious angel" oninput={()=>localStorage.setItem('hp-name',name)}/></label><div class="lobby-actions"><button class="primary" disabled={busy||!name.trim()} onclick={()=>void run(async()=>{const id=await createGame(name);await connect(id);})}>Create a table</button><button disabled={busy} onclick={startPractice}>Practice with computers</button></div><div class="join"><label>Table code or invite link<input bind:value={code} placeholder="Paste an invite"/></label><button disabled={busy||!code||!name.trim()} onclick={()=>void run(async()=>{const id=code.includes('?table=')?new URL(code).searchParams.get('table')!:code.trim();if(!/^[a-f0-9]{12}$/.test(id))throw new Error('Use the table code from your invite.');await joinGame(id,name);await connect(id);})}>Join table</button></div><label class="replay-upload">Open a saved replay<input type="file" accept=".json,application/json" onchange={e=>{const file=e.currentTarget.files?.[0];if(file)void run(()=>openReplay(file));}}/></label><a href={`${base}/gallery?collection=digital`}>Explore the components</a></section>
 {:else if gameState.players.some(p=>p.id===uid)}{#if replayMode}<section class="replay-controls"><button disabled={cursor<=1} onclick={()=>stepReplay(cursor-1)}>←</button><label>Event {cursor} of {replayCount}<input type="range" min="1" max={replayCount} value={cursor} oninput={e=>stepReplay(Number(e.currentTarget.value))}/></label><button disabled={cursor>=replayCount} onclick={()=>stepReplay(cursor+1)}>→</button><select aria-label="Replay viewpoint" bind:value={uid}>{#each gameState.players as p}<option value={p.id}>{p.name}</option>{/each}</select></section>{/if}<GameTable utilities={tableMenu} state={gameState} {uid} busy={busy||replayMode||animationBusy} events={timeline} animateMoves={!replayMode} onAnimating={animationChanged} send={human} {liveDraft} {publish} {tableId}/>{/if}
</main>
<style>
 .at-table{position:fixed;inset:0;padding:0;max-width:none;margin:0}.table-menu{position:relative;z-index:800;color:#d8c18a}.table-menu summary{display:grid;place-items:center;width:29px;height:29px;cursor:pointer;list-style:none;filter:drop-shadow(0 2px 2px #071e16)}.table-menu summary::-webkit-details-marker{display:none}.table-menu summary svg{width:25px;height:25px}.table-menu>div{position:absolute;top:35px;left:0;min-width:155px;padding:8px;background:#eee1bf;box-shadow:0 8px 25px #071e1888;border:1px solid #b99e63;border-radius:8px;display:grid;gap:3px;color:#5c492a}.table-menu a,.table-menu button{display:block;padding:9px 12px;background:none;border:0;text-align:left;font:14px/1.3 inherit;text-decoration:none}.at-table>.error,.at-table>.live-warning{position:fixed;top:30%;left:50%;transform:translateX(-50%);max-width:75vw;z-index:900;background:#fae8cf;box-shadow:0 8px 25px #071e1888}.at-table>.replay-controls{position:fixed;left:10%;right:10%;top:50%;z-index:900}.replay-upload{font-size:14px}.replay-controls{display:flex;gap:12px;align-items:center;padding:12px;background:#ede2c7;border-radius:8px;margin:12px 0}.replay-controls label{flex:1;display:grid;font-size:13px}.replay-controls input{width:100%}:global(body:has(.play-page) .site-header),:global(body:has(.play-page) .site-footer){display:none}.play-page{padding:14px clamp(10px,2vw,30px) 30px;max-width:1660px;margin:auto}.play-header{display:flex;justify-content:space-between;gap:12px;align-items:center}.play-header>a{font:600 31px 'Cormorant Garamond';text-decoration:none}.welcome{max-width:740px;margin:10vh auto;padding:36px;background:#fcf6e8;border:1px solid #c6b07a;border-radius:14px}.welcome h1{font-size:clamp(36px,5vw,56px);line-height:1.05}.welcome p{max-width:55ch}.welcome label{display:grid;gap:6px;margin:20px 0 10px}.welcome input{font:inherit;padding:12px;border:1px solid #bca879;border-radius:5px;background:#fffdf7;max-width:100%}.lobby-actions{display:flex;gap:12px;flex-wrap:wrap}.join{margin:28px 0;display:flex;align-items:end;gap:10px}.join label{flex:1;margin:0}.join button{margin-bottom:0}.error{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:12px 18px;background:#f9ddd7;border:1px solid #a85d4b;border-radius:6px;margin:12px 0}.error button{padding:0;border:0;background:none;min-height:0;font-size:20px}.live-warning{font-size:13px;color:#765b2c}button.primary{background:#56603d;color:#fff9e9}button:disabled{opacity:.5}@media(max-width:600px){.play-header{align-items:start}.play-header>a{font-size:24px;min-width:120px}.welcome{padding:22px;margin:5vh auto}.join{flex-direction:column;align-items:stretch}}
</style>
